import { Component } from '@angular/core';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  usuario = '';
  senha = '';
  erro = false;

  constructor() { }

  // ngOnInit não utilizado

  login() {
    // Exemplo de autenticação simples (substitua por lógica real)
    if (this.usuario === 'admin' && this.senha === 'admin') {
      this.erro = false;
      alert('Login realizado com sucesso!');
      // Redirecionar para área administrativa se desejar
    } else {
      this.erro = true;
    }
  }
}
<div class="login-container">
	<h2>Login Administrativo</h2>
	<form (ngSubmit)="login()" #loginForm="ngForm">
		<label>Usuário:<br>
			<input name="usuario" [(ngModel)]="usuario" required />
		</label><br>
		<label>Senha:<br>
			<input name="senha" [(ngModel)]="senha" required type="password" />
		</label><br>
		<button type="submit" [disabled]="!loginForm.form.valid">Entrar</button>
	</form>
	<div *ngIf="erro" class="erro-login">Usuário ou senha inválidos.</div>
</div>
